const k = $input.first().json.data;
const brl = (v) => Number(v || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const linhas = [
  `📊 Resumo operacional — ${new Date(k.generated_at).toLocaleString('pt-BR')}`,
  '',
  `Estoque: ${k.estoque.materiais_abaixo_do_ponto} material(is) no ponto de reposição; reposição estimada ${brl(k.estoque.valor_estimado_reposicao)}.`,
  ...k.estoque.itens_criticos.map((i) => `  • ${i.material} (${i.centro}): disponível ${i.disponivel}, ponto ${i.ponto}, sugerido ${i.sugerido}`),
  `Compras: ${k.compras.requisicoes_aguardando} RC e ${k.compras.pedidos_aguardando_aprovacao} PC aguardando aprovação; ${k.compras.pedidos_em_aberto} PC em aberto (${brl(k.compras.valor_pedidos_em_aberto)}), ${k.compras.pedidos_atrasados} atrasado(s).`,
  `Vendas: ${k.vendas.pedidos_a_entregar} pedido(s) a entregar (${brl(k.vendas.valor_pedidos_a_entregar)}); faturamento do mês ${brl(k.vendas.faturamento_mes)}.`,
  `Financeiro: ${brl(k.financeiro.valor_em_aberto)} a receber; ${k.financeiro.titulos_atrasados} título(s) atrasado(s) (${brl(k.financeiro.valor_atrasado)}).`,
  '',
  'Fonte: Enterprise ERP Simulator — GET /api/kpis/summary (fórmulas em data.definitions).',
];
return [{ json: { resumo: linhas.join('\n'), indicadores: k } }];
